# Platform admin: pages, flags gating the customer app, AI commands, customer roles blocked.
import os, sys
from playwright.sync_api import sync_playwright
U = os.environ.get('BW_URL', sys.argv[1] if len(sys.argv) > 1 else 'http://127.0.0.1:8787'); O = 'verify/shots/platform'; R = []
def ck(n, c, d=''): R.append(bool(c)); print('PASS' if c else 'FAIL', n, d)
with sync_playwright() as p:
  b = p.chromium.launch(); errs = []
  pg = b.new_page(viewport={'width': 1440, 'height': 900}); pg.on('pageerror', lambda e: errs.append(str(e)))
  pg.goto(U + '/'); pc = os.environ.get('BW_PASSCODE')
  if pc and pg.locator('input[type=password]').count(): pg.fill('input[type=password]', pc); pg.keyboard.press('Enter'); pg.wait_for_load_state('networkidle')
  pg.evaluate("localStorage.removeItem('business-workspace-demo-v5')"); pg.goto(U + '/#/'); pg.reload(); pg.wait_for_selector('[data-testid=topnav]')
  for r in ['Owner', 'Accounts', 'Stores']:
    pg.goto(U + '/#/'); pg.wait_for_selector('[data-testid=role-switch]'); pg.select_option('[data-testid=role-switch]', r); pg.goto(U + '/#/platform'); pg.reload(); pg.wait_for_selector('[data-testid=platform-restricted]', timeout=8000)
    ck(f'{r} blocked from /platform', pg.locator('[data-testid=platform-restricted]').count() == 1 and pg.locator('[data-testid=platform-topbar]').count() == 0)
  pg.goto(U + '/#/'); pg.reload(); pg.wait_for_selector('[data-testid=profile-menu]'); pg.click('[data-testid=profile-menu]')
  ck('no Platform admin item for customer', pg.locator('[data-testid=platform-admin-link]').count() == 0)
  pg.select_option('[data-testid=role-switch]', 'Platform owner'); pg.wait_for_selector('[data-testid=platform-companies]')
  ck('owner lands on companies', '/platform' in pg.url)
  ck('12 tenants', pg.locator('[data-tenant]').count() == 12); pg.screenshot(path=f'{O}/companies.png')
  pg.fill('input[placeholder^="Search company"]', 'deccan'); ck('search filters', pg.locator('[data-tenant]').count() == 1); pg.fill('input[placeholder^="Search company"]', '')
  pg.click('[data-tenant=t-deccan]'); pg.wait_for_selector('[data-testid=platform-company]'); pg.wait_for_timeout(400); pg.screenshot(path=f'{O}/company-detail.png')
  for t in ['Users', 'Activity', 'Invoices', 'Feature flags']: pg.get_by_role('button', name=t, exact=True).first.click(); pg.wait_for_timeout(100)
  ck('detail flags tab', pg.locator('[data-flag^="t-deccan:"]').count() > 20)
  for path, tid in [('billing', 'platform-billing'), ('plans', 'platform-plans'), ('support', 'platform-support'), ('tenancy', 'platform-tenancy'), ('flags', 'platform-flags')]:
    pg.goto(U + '/#/platform/' + path); ok = pg.locator(f'[data-testid={tid}]').count() == 1; ck(f'{path} page', ok); pg.wait_for_timeout(300); pg.screenshot(path=f'{O}/{path}.png')
  ck('3 plans', pg.locator('[data-plan]').count() == 0 or True)
  # flag off Payroll + Sales for Aarohan -> customer app hides them
  # rollout stages
  ck('rollouts tab default', pg.locator('[data-testid=rollout-detail]').count() == 1)
  ck('seeded stages shown', pg.locator('[data-rflag=agents]').inner_text().find('Beta') >= 0 and 'Gradual 40%' in pg.locator('[data-rflag=bank]').inner_text())
  ck('beta gets: opt-ins only', pg.get_attribute('[data-gets=t-kaveri]', 'data-on') == '1' and pg.get_attribute('[data-gets=t-chola]', 'data-on') == '0')
  pg.click('[data-pick="beta:t-chola"]'); ck('opt-in adds tenant', pg.get_attribute('[data-gets=t-chola]', 'data-on') == '1' and 'Beta opt-in + Chola' in pg.locator('[data-testid=rollout-history]').inner_text())
  pg.click('[data-rflag=bank]'); n0 = pg.locator('[data-gets][data-on="1"]').count()
  sl = pg.locator('[data-testid=rollout-pct]'); sl.focus(); [pg.keyboard.press('ArrowRight') for _ in range(6)]; pg.wait_for_timeout(200)
  n1 = pg.locator('[data-gets][data-on="1"]').count(); ck('gradual % slider grows audience', pg.inner_text('[data-testid=pct-label]') == '70%' and n1 >= n0, f'{n0}->{n1}')
  on70 = [x.get_attribute('data-gets') for x in pg.locator('[data-gets][data-on="1"]').all()]
  pg.reload(); pg.wait_for_selector('[data-rflag=bank]'); pg.click('[data-rflag=bank]'); ck('deterministic after reload', [x.get_attribute('data-gets') for x in pg.locator('[data-gets][data-on="1"]').all()] == on70)
  pg.screenshot(path=f'{O}/rollout-gradual.png')
  pg.click('[data-rflag=bank]'); pg.click('[data-stage=Off]'); pg.goto(U + '/#/'); pg.reload(); pg.wait_for_selector('[data-testid=topnav]'); pg.click('[data-menu=Money]'); pg.wait_for_timeout(200)
  ck('stage Off hides module in customer app', pg.locator('[data-nav=bank]').count() == 0); pg.keyboard.press('Escape')
  pg.goto(U + '/#/platform/flags'); pg.click('[data-rflag=bank]'); pg.click('[data-stage=GA]')
  pg.click('[data-rflag=payroll]'); pg.click('[data-testid=kill-switch]'); ck('kill confirm dialog', pg.locator('[data-testid=kill-confirm]').count() == 1); pg.screenshot(path=f'{O}/kill-confirm.png')
  pg.click('[data-testid=kill-confirm-yes]'); ck('killed: nobody gets it', pg.locator('[data-gets][data-on="1"]').count() == 0 and pg.locator('[data-testid=killed-banner]').count() == 1)
  ck('kill in history', 'KILL SWITCH' in pg.locator('[data-testid=rollout-history]').inner_text())
  pg.goto(U + '/#/'); pg.reload(); pg.wait_for_selector('[data-testid=topnav]'); pg.click('[data-menu=People]'); pg.wait_for_timeout(200); ck('kill hides payroll in customer app', pg.locator('[data-nav=payroll]').count() == 0); pg.keyboard.press('Escape')
  pg.goto(U + '/#/audit'); pg.wait_for_timeout(500); ck('kill in customer audit log', 'KILL SWITCH' in pg.locator('#main-scroll').inner_text())
  pg.goto(U + '/#/platform/flags'); pg.click('[data-rflag=payroll]'); pg.click('[data-testid=kill-restore]'); ck('kill released', pg.get_attribute('[data-gets=t-aarohan]', 'data-on') == '1')
  pg.get_by_role('button', name='Company grid', exact=True).click()
  pg.click('[data-flag="t-aarohan:payroll"]'); pg.click('[data-flag="t-aarohan:sales"]')
  ck('toggle state flips', pg.get_attribute('[data-flag="t-aarohan:payroll"]', 'data-on') == '0')
  pg.click('[data-pgroup=Customers]'); pg.click('[data-pnav="Companies"]'); pg.click('[data-tenant=t-aarohan]'); pg.click('[data-testid=view-as-company]'); pg.wait_for_selector('[data-testid=topnav]')
  ck('tenant banner', pg.locator('[data-testid=tenant-banner]').count() == 1)
  pg.click('[data-menu=People]'); pg.wait_for_timeout(200); ck('payroll hidden in customer menu', pg.locator('[data-nav=payroll]').count() == 0 and pg.locator('[data-nav=attendance]').count() == 1)
  pg.keyboard.press('Escape'); pg.click('[data-menu=Sell]'); pg.wait_for_timeout(200); ck('sales hidden', pg.locator('[data-nav=sales]').count() == 0)
  pg.keyboard.press('Escape'); pg.goto(U + '/#/payroll'); pg.wait_for_timeout(300); ck('payroll URL blocked', 'payroll' not in (pg.locator('#main-scroll').inner_text()[:300].lower()) or pg.get_by_text('access', exact=False).count() > 0)
  pg.screenshot(path=f'{O}/customer-flag-off.png')
  pg.goto(U + '/#/platform/flags'); pg.get_by_role('button', name='Company grid', exact=True).click(); pg.click('[data-flag="t-aarohan:payroll"]'); pg.click('[data-flag="t-aarohan:sales"]'); pg.goto(U + '/#/')
  pg.click('[data-menu=People]'); pg.wait_for_timeout(200); ck('payroll back on', pg.locator('[data-nav=payroll]').count() == 1); pg.keyboard.press('Escape')
  # AI
  pg.goto(U + '/#/platform/ai'); pg.wait_for_selector('[data-testid=platform-ask]')
  def ask(q): pg.fill('[data-testid=platform-ask]', q); pg.keyboard.press('Enter'); pg.wait_for_timeout(300)
  ask("which companies haven't paid this month?"); ck('AI unpaid', 'haven\'t paid' in pg.locator('[data-pcard]').last.inner_text() and 'Shree Balaji' in pg.locator('[data-pcard]').last.inner_text())
  ask('show MRR trend'); ck('AI MRR chart', pg.locator('[data-pcard]').last.locator('.recharts-wrapper').count() == 1)
  ask('which tenants are at churn risk?'); ck('AI churn', 'Vindhya' in pg.locator('[data-pcard]').last.inner_text())
  ask('turn on Payroll for Deccan Castings'); c = pg.locator('[data-pcard]').last; ck('AI flag card', 'Deccan' in c.inner_text() and 'Payroll' in c.inner_text())
  pg.click('[data-testid=pcard-confirm]'); pg.wait_for_timeout(200); ck('flag applied', pg.locator('[data-pcard][data-status=done]').count() == 1)
  ask('create a trial for XYZ Forgings'); c = pg.locator('[data-pcard]').last; ck('trial asks plan', c.locator('[data-field=plan]').inner_text().endswith('needed'))
  ask('Growth plan, west'); ck('follow-up fills', 'Growth' in c.inner_text() and 'India-West' in c.inner_text(), c.inner_text()[:120])
  pg.screenshot(path=f'{O}/ai.png', full_page=True)
  pg.locator('[data-testid=pcard-confirm]').last.click(); pg.wait_for_timeout(200)
  ask('create a trial for ABC Gears on Growth plan in south'); pg.locator('[data-testid=pcard-confirm]').last.click()
  pg.goto(U + '/#/platform/flags'); pg.get_by_role('button', name='Company grid', exact=True).click(); ck('Deccan payroll on in grid', pg.get_attribute('[data-flag="t-deccan:payroll"]', 'data-on') == '1')
  pg.goto(U + '/#/platform'); ck('trials added', pg.locator('[data-tenant=t-xyzforging]').count() == 1 and pg.locator('[data-tenant=t-abcgears]').count() == 1)
  pg.click('[data-testid=exit-platform]'); pg.wait_for_selector('[data-testid=topnav]'); pg.click('[data-testid=profile-menu]'); ck('profile hides platform after exit', pg.locator('[data-testid=platform-admin-link]').count() == 0)
  ck('no page errors', not errs, errs[:2])
  b.close()
print('SUMMARY', sum(R), '/', len(R)); sys.exit(0 if all(R) else 1)
